			function checkTimes(param) {
				//스케쥴이 잡혀있으면 true 반환 otherwise false.
				var ret = true;
				if (param.TIME0 == '' && param.TIME1 == '' && param.TIME2 == '' &&
					param.TIME3 == '' && param.TIME4 == '' && param.TIME5 == '' &&
					param.TIME6 == ''
				) {
					ret = false;
				} else {
					ret = true;
				}
				
				return ret;
			}

