			function drawHeaderColAuto1(){
				var dsTimes = app.lookup('dsTimes');
				var arrDsTimes = dsTimes.getRowDataRanged();
				var dsListCnslt = app.lookup('dsListCnslt');
				var arrDsListCnslt = dsListCnslt.getRowDataRanged();
				var vcGrid = app.lookup("grdList");
				vcGrid.resetGrid();
				
				//console.log(arrDsTimes.length);
				for(var idx = 0 ; idx < arrDsTimes.length ; idx++){
					//console.log(idx);
					vcGrid.addColumn({
						columnLayout: [{
							width: "100px"
						}],
						header : [{
							constraint: {
								rowIndex : 0,
								colIndex : 4+idx
							},
							configurator: function(cell){
								cell.text = arrDsTimes[idx].PERIODS;
							}
						}],
						detail: [{
							constraint: {
								rowIndex : 0,
								colIndex : 4+idx
							},
							configurator: function(cell){
								cell.columnName = 'TIME'+idx;
							}
						}]
					});
					
				}
				
				
			}

			function drawHeaderColAuto2(){
				var dsTimes = app.lookup('dsTimes');
				var arrDsTimes = dsTimes.getRowDataRanged();
				var dsListCnslt = app.lookup('dsListCnslt');
				var arrDsListCnslt = dsListCnslt.getRowDataRanged();
				var vcGrid = app.lookup("grdList");
				vcGrid.resetGrid();
				var lenOutReach = arrDsTimes.length*2;
				var index = 0;
				for(var idx = 0 ; idx < lenOutReach ; idx++){
					vcGrid.addColumn({
						columnLayout: [{
							width: "100px"
						}],
						header : [{
							constraint: {
								rowIndex : 0,
								colIndex : 4+idx
							},
							configurator: function(cell){
								
								if(idx % 2 == 0 && idx != 0) index++;
								
								var time = arrDsTimes[index].PERIODS.split('~');
								var startTime,endTime;
								startTime = Number(time[0].trim().substr(0,2));
								endTime = Number(time[1].trim().substr(0,2));
								var diffHour = Math.abs(endTime - startTime);
								var beforeTime = '';
								var afterTime = '';
								startTime = startTime == 0 ? '00':startTime+'';
								endTime = endTime == 0 ? '00':endTime+''; 
								if(diffHour%4 == 0){
									var tempStime = (Number(startTime)+2)<10?'0'+(Number(startTime)+2) : (Number(startTime)+2);
									beforeTime = time[0].trim() + '~' + time[0].trim().replace(startTime,tempStime+'');
									afterTime =  time[0].trim().replace(startTime,tempStime+'') + '~' + time[1].trim();
								}
								
								if(idx % 2 ==0)
									cell.text = beforeTime;
								else
									cell.text = afterTime;
							}
						}],
						detail: [{
							constraint: {
								rowIndex : 0,
								colIndex : 4+idx
							},
							configurator: function(cell){
								cell.columnName = 'TIME'+idx;
							}
						}]
					});
					
				}
				
			}

